import React from "react";
import backgroundImage from "../assets/spiceee.jpg";
import steak from "../assets/steak.png";
import seafood from "../assets/seafood.png";
import chicken from "../assets/chicken.png";
import potato from "../assets/potato.png";
import pasta from "../assets/italian.png";
import mexican from "../assets/mexican.png";


function Grill() {
  const products = [
    {
      id: 1,
      name: "Steak Spice",
      description:
        "A robust blend that enhances the smoky, savory flavor of grilled steak.",
      image: steak,
    },
    {
      id: 2,
      name: "SeaFood Spice",
      description:
        "A zesty mix perfect for seasoning seafood, adding a burst of coastal flavor.",
      image: seafood,
    },
    {
      id: 3,
      name: "Chicken Spice",
      description:
        "A savory blend with garlic and herbs to bring out the best in chicken dishes.",
      image: chicken,
    },
    {
      id: 4,
      name: "Potato Spice",
      description:
        "Smooth, creamy, and buttery, with hints of garlic to elevate potato dishes.",
      image: potato,
    },
    {
      id: 5,
      name: "Pasta Spice",
      description:
        "An aromatic mix of herbs for a light, flavorful addition to pasta.",
      image: pasta,
    },
    {
      id: 6,
      name: "Mexican Mix",
      description:
        "A spicy, vibrant blend of tomatoes, onions, and herbs, ideal for dips.",
      image: mexican,
    },
    
   
  ];

  return (
    <div>
      <style>
        {`
          @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600&family=Roboto:wght@300&display=swap');

          .font-playfair {
            font-family: 'Playfair Display', serif;
          }

          .font-roboto {
            font-family: 'Roboto', sans-serif;
            font-size: 0.95rem;
          }

          .shadow-lg:hover {
            box-shadow: 0 8px 20px rgba(0, 0, 0, 0.15);
          }

          .transition-shadow {
            transition: box-shadow 0.3s ease-in-out;
          }
        `}
      </style>

      <div
        className="min-h-screen bg-cover bg-center p-10 flex items-center justify-center"
        style={{
          backgroundImage: `url(${backgroundImage})`, // Set the background image here
          backgroundSize: "cover", // Ensure it covers the entire section
          backgroundPosition: "center", // Center the image
        }}
      >
        <div className="max-w-7xl w-full bg-white bg-opacity-60  rounded-lg">
          <h1 className="text-center text-5xl font-bold text-orange-600 mb-10 font-playfair">
            Our Exclusive Products
          </h1>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
            {products.map((product) => (
              <div
                key={product.id}
                className="bg-white p-6 rounded-2xl shadow-lg hover:shadow-xl transition-shadow duration-300 group transform hover:scale-105"
              >
                <img
                  src={product.image}
                  alt={product.name}
                  className="w-full h-40 object-contain rounded-lg mb-4"
                />
                <h2 className="text-2xl font-semibold text-gray-800 group-hover:text-orange-600 mb-3 font-playfair">
                  {product.name}
                </h2>
                <p className="text-gray-600 group-hover:text-gray-800 mb-4 font-roboto">
                  {product.description}
                </p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Grill;
